import java.util.StringTokenizer

fun main() {
    val br = System.`in`.bufferedReader()
    val firstLine = StringTokenizer(br.readLine())
    val n = firstLine.nextToken().toInt()
    val m = firstLine.nextToken().toInt()

    val aTokens = StringTokenizer(br.readLine())
    val bTokens = StringTokenizer(br.readLine())

    val setA = mutableSetOf<Int>()
    val setB = mutableSetOf<Int>()

    repeat(n) {
        setA.add(aTokens.nextToken().toInt())
    }
    repeat(m) {
        setB.add(bTokens.nextToken().toInt())
    }

    // Check for common digit
    var common: Int? = null
    for (d in setA) {
        if (setB.contains(d)) {
            if (common == null || d < common!!) {
                common = d
            }
        }
    }

    if (common != null) {
        println(common)
        return
    }

    // No common digit: form smallest two-digit number
    var minA = 10
    var minB = 10
    for (d in setA) if (d < minA) minA = d
    for (d in setB) if (d < minB) minB = d

    val ans1 = minA * 10 + minB
    val ans2 = minB * 10 + minA
    println(minOf(ans1, ans2))
}

